def solution() -> int:
    # Given rod length N and prices for each rod length in list P
    N = 8
    P = [28, 13, 20, 19, 32, 26, 3, 31]  # prices for lengths 1 to 8

    # dp[i] will store the maximum revenue for rod of length i
    dp = [0] * (N + 1)

    # Compute maximum revenue for each length from 1 to N
    for i in range(1, N + 1):
        max_val = float('-inf')
        # Try all possible first cut lengths j (1-indexed)
        for j in range(1, i + 1):
            # if j is the current piece we take, then revenue is P[j-1] + dp[i - j]
            current_revenue = P[j - 1] + dp[i - j]
            if current_revenue > max_val:
                max_val = current_revenue
        dp[i] = max_val

    return int(dp[N])

