def solution() -> int:
    # Define problem parameters
    profit = [21, 20, 20, 14]
    consumption = [
        [22, 7, 7, 18],  # Resource 1
        [9, 2, 26, 8],   # Resource 2
        [19, 31, 29, 19],# Resource 3
        [9, 14, 18, 13]  # Resource 4
    ]
    capacity = [32, 29, 20, 13]
    upper_bounds = [3, 3, 3, 3]

    max_profit = 0

    # There are 4 decision variables x0, x1, x2, x3
    # We will try every integer combination from 0 to 3 for each variable
    for x0 in range(upper_bounds[0] + 1):
        for x1 in range(upper_bounds[1] + 1):
            for x2 in range(upper_bounds[2] + 1):
                for x3 in range(upper_bounds[3] + 1):
                    x = [x0, x1, x2, x3]

                    # Check resource constraints for each resource i
                    feasible = True
                    for i in range(len(capacity)):
                        consumption_sum = consumption[i][0] * x[0] + consumption[i][1] * x[1] + \
                                          consumption[i][2] * x[2] + consumption[i][3] * x[3]
                        if consumption_sum > capacity[i]:
