                    if feasible:
                        # Calculate profit for this combination
                        current_profit = profit[0] * x[0] + profit[1] * x[1] + profit[2] * x[2] + profit[3] * x[3]
                        if current_profit > max_profit:
                            max_profit = current_profit
    return max_profit

