    graph = {
        0: [(3, 3)],
        2: [(0, 2)],
        3: [(4, 2), (1, 7)],
        4: [(0, 2), (1, 2)]
    }

    # We use Dijkstra's algorithm to compute the shortest path from 0 to 4
    import heapq

    start, end = 0, 4
    # Initialize distances for nodes in graph; default is infinity
    distances = {node: float('inf') for node in graph}
    # Ensure we include nodes that could only appear as neighbors
    for edges in graph.values():
        for neighbor, _ in edges:
            if neighbor not in distances:
                distances[neighbor] = float('inf')

    distances[start] = 0
    parent = {}  # To reconstruct the path
    pq = [(0, start)]
    visited = set()

    while pq:
        dist, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        if node == end:
            break
        for neighbor, weight in graph.get(node, []):
            new_dist = dist + weight
            if new_dist < distances.get(neighbor, float('inf')):
                distances[neighbor] = new_dist
                parent[neighbor] = node
                heapq.heappush(pq, (new_dist, neighbor))

    # Reconstruct the path from end to start
    path = []
    if distances[end] != float('inf'):
        current = end
        while current != start:
            path.append(current)
            current = parent[current]
        path.append(start)
        path.reverse()

    total_distance = distances[end]
    return path, int(total_distance)

