    from heapq import heappush, heappop

    # Define the directed graph using an adjacency list
    graph = {
        0: [(1, 5), (4, 1), (3, 4)],
        1: [(2, 2)],
        2: [],
        3: [(2, 2)],
        4: [(1, 7)]
    }

    start, end = 0, 4

    # Priority queue holds tuples of (distance, current_node, path_so_far)
    pq = [(0, start, [start])]
    visited = set()

    while pq:
        dist, node, path = heappop(pq)
        if node == end:
            return (path, dist)
        if node in visited:
            continue
        visited.add(node)
        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                heappush(pq, (dist + weight, neighbor, path + [neighbor]))

    # If no path found, return empty path and distance 0
    return ([], 0)

if __name__ == '__main__':
    path, total_distance = solution()
    print(path, total_distance)

