def solution():
    from typing import List, Tuple

    # Define the graph as an adjacency list; each entry is (neighbor, weight).
    # Graph is directed as per the problem description.
    graph = {
        0: [(4, 1)],
        1: [(0, 1), (3, 7)],
        2: [(1, 7)],
        3: [(0, 1), (4, 6)],
        4: []
    }

    # We'll use a simple implementation of Dijkstra's algorithm.
    import heapq

    start, target = 0, 4
    # Distance dictionary
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    # parent to reconstruct path
    parent = {node: None for node in graph}

    # Priority Queue holds (distance, node)
    heap = [(0, start)]

    while heap:
        current_dist, node = heapq.heappop(heap)
        if current_dist > dist[node]:
            continue
        if node == target:
            # reached target, but we need full path processing
            continue
        for neighbor, weight in graph[node]:
            if dist[neighbor] > current_dist + weight:
                dist[neighbor] = current_dist + weight
                parent[neighbor] = node
                heapq.heappush(heap, (dist[neighbor], neighbor))

    # Reconstruct path from start to target
    path = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = parent[cur]
    path.reverse()

    # Ensure the path starts with start and ends with target
    if path[0] != start or path[-1] != target:
        return ([], 0)

    return (path, dist[target])

if __name__ == '__main__':
    result = solution()
    print(result)

