def solution():
    from heapq import heappush, heappop

    # building an undirected graph from given edges
    graph = {
        0: {1: 5, 3: 1},
        1: {0: 5, 3: 8, 4: 7},
        2: {3: 1, 5: 6},
        3: {0: 1, 1: 8, 4: 1, 2: 1},
        4: {1: 7, 3: 1},
        5: {2: 6}
    }

    start, end = 0, 5
    # Dijkstra's algorithm initialization
    dist = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    dist[start] = 0

    heap = [(0, start)]
    while heap:
        d, u = heappop(heap)
        if u == end:
            break
        if d > dist[u]:
            continue
        for v, weight in graph[u].items():
            alt = d + weight
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heappush(heap, (alt, v))

    # reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()

    total_distance = dist[end]
    return path, total_distance

if __name__ == '__main__':
    path, total = solution()
