def solution():
    # Define the graph with vertices and their neighbors
    graph = {
        1: [2, 4, 5],
        2: [1, 3, 6],
        3: [2],
        4: [1, 5, 7, 8],
        5: [1, 4],
        6: [2, 7],
        7: [4, 6, 8],
        8: [4, 7]
    }

    # List of available colors
    available_colors = ['A', 'B', 'C']
    colors = {}

    # Greedy coloring: Visit vertices from 1 to 8
    for vertex in range(1, 9):
        forbidden = set()
        for neighbor in graph[vertex]:
            if neighbor in colors:
                forbidden.add(colors[neighbor])
        for color in available_colors:
            if color not in forbidden:
                colors[vertex] = color
                break

    return colors

if __name__ == '__main__':
    print(solution())

